<script setup lang="ts">
import {ref,watch,onMounted} from 'vue';import {api,statusName,displayTime} from '../lib/api';
interface Row{id:string;public_number:string;title:string;status:string;event_name:string;updated_at:string}
const rows=ref<Row[]>([]),total=ref(0),page=ref(1),status=ref(''),busy=ref(false),error=ref('');let sequence=0;
async function load(){const seq=++sequence;busy.value=true;error.value='';try{const result=await api<{items:Row[];total:number}>('/api/submissions?'+new URLSearchParams({page:String(page.value),status:status.value}));if(seq===sequence){rows.value=result.items;total.value=result.total;}}catch(e){if(seq===sequence)error.value=(e as Error).message;}finally{if(seq===sequence)busy.value=false;}}
watch(status,()=>{page.value=1;void load();});watch(page,()=>void load());onMounted(load);
</script>
<template><div class="page"><header class="page-head"><h1>我的投稿</h1><RouterLink class="button primary" to="/submit/new">新建投稿</RouterLink></header><label>投稿状态<select v-model="status"><option value="">全部状态</option><option value="draft">草稿</option><option value="pending">待审核</option><option value="rejected">已驳回</option><option value="approved">已通过</option></select></label><p v-if="error" role="alert" class="alert error">{{ error }}</p><p v-if="busy" role="status">正在读取投稿…</p><section v-for="row in rows" :key="row.id" class="paper"><div class="inline"><h2 class="grow"><RouterLink :to="'/submit/'+row.id">{{ row.title||'未命名草稿' }}</RouterLink></h2><span class="badge" :class="row.status">{{ statusName(row.status) }}</span></div><p class="hint">{{ row.event_name }} · {{ row.public_number }}<br>最近更新：{{ displayTime(row.updated_at) }}</p><RouterLink class="button" :to="'/submit/'+row.id">{{ ['draft','rejected'].includes(row.status)?'继续填写':'查看投稿' }}</RouterLink></section><p v-if="!busy&&!rows.length" class="empty">{{ status?'没有此状态的投稿。':'还没有投稿，可点击“新建投稿”开始填写。' }}</p><div class="pagination"><button :disabled="busy||page===1" @click="page--">上一页</button><span>第 {{ page }} 页 · 共 {{ total }} 份</span><button :disabled="busy||page*20>=total" @click="page++">下一页</button></div></div></template>
